using System;using System.Linq;using System.Collections.Concurrent;using System.Reflection;using TGLL;
class ActivitySequenceTests {
 static ConcurrentDictionary<string,NativeJob> jobs=(ConcurrentDictionary<string,NativeJob>)typeof(NativeBackend).GetField("jobs",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);
 static DateTime now=new DateTime(2026,11,7,0,0,0,DateTimeKind.Utc);static int starts;
 static void C(bool b,string m){if(!b)throw new Exception(m);}
 static NativeJob J(string name,bool dungeon=true,bool curse=true,bool quest=false,bool soncap=false,bool beast=false){var j=new NativeJob("synthetic.exe",name,"unused",null,true){State="opened",TrainReady=true,GameSettingsReady=true,MapId=59,CharacterName=name};jobs[j.Id]=j;NativeBackend.ConfigureActivitySequence(j.Id,false,dungeon,curse,quest,soncap,beast,false);return j;}
 static void Start(NativeJob j,int stage){starts++;j.DailyExecuting=true;if(stage==2)j.DungeonHighEnabled=true;if(stage==3)j.IzanamiEnabled=true;if(stage==4)j.QuestEnabled=true;if(stage==5)j.SonCapEnabled=true;if(stage==6){j.BeastQuestEnabled=true;j.QuestEnabled=true;}}
 static void Tick(params NativeJob[] team){foreach(var j in team)NativeBackend.PulseActivitySequence(j,now,Start);now=now.AddSeconds(1);}
 static int Main(){try{NativeBackend.LogDirectory=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"qltk-sequence-tests");
  NativeBackend.DailyDungeonLimit=100;NativeBackend.DailyIzanamiLimit=3;NativeBackend.DailyQuestLimit=100;NativeBackend.DailySonCapLimit=6;
  var a=J("1");var b=J("2");var c=J("3");var ids=new[]{a.Id,b.Id,c.Id};NativeBackend.ConfigureSequenceTeams(new[]{ids},new string[0][]);
  Tick(a,b,c);C(starts==3&&a.DailyStage==2&&c.DungeonHighEnabled,"all start dungeon under its limit");
  a.DungeonFinished=b.DungeonFinished=true;Tick(a,b,c);C(a.DailyStage==3&&!a.IzanamiEnabled&&!b.IzanamiEnabled&&c.DailyStage==2&&c.DungeonHighEnabled,"1/2 wait, 3 keeps dungeon");
  int n=starts;for(int i=0;i<20;i++)Tick(a,b,c);C(starts==n&&c.DungeonHighEnabled,"waiting never preempts/restarts previous stage");
  var x=J("4",false,true);var y=J("5",false,true);var z=J("6",false,true);NativeBackend.ConfigureSequenceTeams(new[]{ids,new[]{x.Id,y.Id,z.Id}},new string[0][]);Tick(x,y,z);Tick(x,y,z);C(x.IzanamiEnabled&&z.IzanamiEnabled,"other ready team proceeds while team123 waits");
  c.DungeonFinished=true;c.MapId=18;Tick(c);C(c.DailyStage==2,"must actually leave dungeon before switching");c.MapId=59;Tick(c,a,b);C(!a.IzanamiEnabled&&a.DailyStage==3,"capacity held by other active team");
  foreach(var j in new[]{x,y,z})j.IzanamiNoAttempts=true;Tick(x,y,z);Tick(a,b,c);C(a.IzanamiEnabled&&b.IzanamiEnabled&&c.IzanamiEnabled&&a.DailyExecuting,"3 finishes, all three start curse automatically");
  foreach(var j in new[]{a,b,c}){j.IzanamiNoAttempts=true;}Tick(a,b,c);C(a.SequenceFinished&&b.SequenceFinished&&c.SequenceFinished,"team completion survives first member advancing");
  jobs.Clear();starts=0;var single=J("all",true,false,true,false,true);Tick(single);single.DungeonFinished=true;Tick(single);C(single.DailyStage==4&&single.QuestEnabled,"dungeon to weekly");single.QuestFinished=true;Tick(single);C(single.DailyStage==6&&single.BeastQuestEnabled,"weekly to beast");single.QuestFinished=false;Tick(single);C(!single.SequenceFinished,"does not complete before beast receipt");single.QuestFinished=true;Tick(single);C(single.SequenceFinished&&!single.BeastQuestEnabled,"beast completes last");
  jobs.Clear();var old=J("adopt",true,true);old.SequenceManaged=false;old.DailyManaged=false;old.DungeonHighEnabled=true;old.DungeonCycleWaiting=true;old.MapId=18;NativeBackend.ConfigureActivitySequence(old.Id,false,true,true,false,false,false,false);C(old.DailyStage==2&&old.DailyExecuting&&old.DungeonHighEnabled,"existing dungeon adopted");
  var resume=J("in-dungeon",false,false);resume.SequenceManaged=false;resume.DailyManaged=false;resume.MapId=18;NativeBackend.ConfigureActivitySequence(resume.Id,true,true,true,false,false,false,false);C(resume.DailyStage==2&&!resume.DailyExecuting,"existing map with disabled auto must initialize dungeon resume before key/travel");NativeBackend.PulseActivitySequence(resume,now);C(resume.DailyExecuting&&resume.DungeonHighEnabled&&!resume.ReceiveFlowActive,"initialize current dungeon without town teleport");
  var next=new NativeJob("synthetic.exe","adopt","unused",null,true){State="opened",TrainReady=true,GameSettingsReady=true,MapId=59};jobs[next.Id]=next;NativeBackend.ConfigureSequenceTeams(new[]{new[]{old.Id}},new string[0][]);C(NativeBackend.TransferDailyPriority(old.Id,next.Id)&&next.SequenceManaged&&!old.SequenceManaged&&next.DailyStage==2&&!next.DailyExecuting,"reconnect resumes exact stage without stale inflight");C(next.SequenceCurseTeam[0]==next.Id,"team member rebound");
  NativeBackend.PulseActivitySequence(next,now);C(next.DungeonHighEnabled&&next.DailyExecuting,"real native dispatch restarts dungeon on new process");
  var beast=J("realbeast",false,false,false,false,true);NativeBackend.PulseActivitySequence(beast,now);C(beast.SequenceManaged&&beast.DailyManaged&&beast.BeastQuestEnabled,"real beast dispatch retains coordinator ownership");
  var up=J("return-up",false,false,true);up.SequenceDone[3]=true;up.UpRequested=true;up.SequenceCloseAfter=true;NativeBackend.PulseActivitySequence(up,now);C(!up.SequenceFinished&&!up.CloseRequested,"Up without destination keeps game and waits");up.FarmChoices=new[]{new FarmSpot{MapId=74,MapName="River",MobId=1,MobName="Mob",Level=52,X=100,Y=100,Zone=1}};up.FarmLevel=52;NativeBackend.PulseActivitySequence(up,now);C(up.SequenceFinished&&up.PersistentUp&&up.UpRequested&&up.FarmEnabled&&!up.SequenceManaged&&up.UpCompleted.All(v=>v),"return to saved Up without replaying completed activities");
  Console.WriteLine("PASS: 1/2 wait for 3 to exit dungeon; independent ready team, stage limits, no preemption/duplicate start, team completion, selected stages, beast receipt, existing dungeon adoption and reconnect continuation; no real game launched.");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
